describe('File Upload Confirmation', () => {
  beforeEach(() => {
    cy.visit('/upload');
  });

  it('should successfully upload a small text file and display confirmation', () => {
    // Intercept the file upload API endpoint
    cy.intercept('POST', '/api/upload').as('uploadFile');

    // Find the file input and select a small text file
    cy.get('[data-testid="file-upload"]').selectFile('cypress/fixtures/sample-text.txt', {
      force: true
    });

    // Find and click the submit button
    cy.get('[data-testid="file-submit"]').click();

    // Wait for the upload API call to complete
    cy.wait('@uploadFile');

    // Verify the success page is displayed
    cy.get('[data-testid="success-page"]').should('be.visible');

    // Verify the page title contains 'File Uploaded!'
    cy.get('[data-testid="page-title"]').should('contain', 'File Uploaded!');

    // Verify the uploaded file's name is displayed
    cy.get('[data-testid="uploaded-files"]').should('be.visible');
    cy.get('[data-testid="uploaded-files"]').should('contain', 'sample-text.txt');

    // Verify the success message is visible
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'File successfully uploaded');
  });

  it('should handle empty file selection and display error message', () => {
    // Intercept the file upload API endpoint
    cy.intercept('POST', '/api/upload').as('uploadFile');

    // Find the file input and clear it
    cy.get('[data-testid="file-upload"]').selectFile('cypress/fixtures/empty.txt', {
      force: true
    });

    // Find and click the submit button
    cy.get('[data-testid="file-submit"]').click();

    // Wait for the upload API call to complete
    cy.wait('@uploadFile');

    // Verify the error page is displayed
    cy.get('[data-testid="error-page"]').should('be.visible');

    // Verify the error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please select a file to upload');

    // Verify the file input is still visible for retry
    cy.get('[data-testid="file-upload"]').should('be.visible');
  });
});
